package io.hsiaopingkuo.stockholdings.entity;

import java.math.BigDecimal;
import java.time.LocalDateTime;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/**
 * 一筆持股，對應 V1__create_holding.sql 的 holding 表。
 * 資料表由 Flyway 建立，這裡的 @Column 只是對應欄位，Hibernate 啟動時會檢查兩邊一致（ddl-auto=validate）。
 */
@Entity
@Table(name = "holding")
public class Holding {

	@Id
	// IDENTITY：由資料庫自動編號，對應 SQL 的 GENERATED BY DEFAULT AS IDENTITY
	@GeneratedValue(strategy = GenerationType.IDENTITY)
	private Long id;

	@Column(name = "code", nullable = false, length = 10)
	private String code;

	@Column(name = "lots", nullable = false)
	private int lots;

	@Column(name = "buy_price", nullable = false, precision = 12, scale = 2)
	private BigDecimal buyPrice;

	@Column(name = "created_at", nullable = false)
	private LocalDateTime createdAt;

	@Column(name = "updated_at", nullable = false)
	private LocalDateTime updatedAt;

	// JPA 規定要有無參數建構子（讀資料庫時用）；設成 protected，避免其他程式建出欄位是空的持股
	protected Holding() {
	}

	// 時間由呼叫端傳入（service 用台北時區的 Clock 算好），Entity 自己不碰系統時間
	public Holding(String code, int lots, BigDecimal buyPrice, LocalDateTime now) {
		this.code = code;
		this.lots = lots;
		this.buyPrice = buyPrice;
		this.createdAt = now;
		this.updatedAt = now;
	}

	// 修改只開放張數和買進價：代號建立後就不能改（和 App API 的 PUT 規格一致）
	public void update(int lots, BigDecimal buyPrice, LocalDateTime now) {
		this.lots = lots;
		this.buyPrice = buyPrice;
		this.updatedAt = now;
	}

	public Long getId() {
		return id;
	}

	public String getCode() {
		return code;
	}

	public int getLots() {
		return lots;
	}

	public BigDecimal getBuyPrice() {
		return buyPrice;
	}

	public LocalDateTime getCreatedAt() {
		return createdAt;
	}

	public LocalDateTime getUpdatedAt() {
		return updatedAt;
	}
}
